import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEM = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/;
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasExactKeys(value, keys) {
  const own = Reflect.ownKeys(value);
  return own.length === keys.length && keys.every(key => Object.hasOwn(value, key));
}

function isPortablePath(value) {
  if (typeof value !== 'string' || value.length === 0) return false;
  return value.split('/').every(segment =>
    SEGMENT.test(segment) && !DEVICE_STEM.test(segment.split('.')[0]));
}

function validateManifest(manifest) {
  if (!isPlainObject(manifest) || !hasExactKeys(manifest, ['writes', 'deletes'])
      || !Array.isArray(manifest.writes) || !Array.isArray(manifest.deletes)) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest must contain exactly writes and deletes arrays');
  }
  const targets = [];
  for (let i = 0; i < manifest.writes.length; i++) {
    const item = manifest.writes[i];
    if (!isPlainObject(item) || !hasExactKeys(item, ['path', 'content'])
        || typeof item.path !== 'string' || typeof item.content !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Each write must be exactly {path, content} with string values');
    }
    targets.push(item.path);
  }
  for (let i = 0; i < manifest.deletes.length; i++) {
    const item = manifest.deletes[i];
    if (typeof item !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Each delete must be a path string');
    }
    targets.push(item);
  }
  for (const target of targets) {
    if (!isPortablePath(target)) throw fail('ERR_INVALID_PATH', `Invalid path: ${JSON.stringify(target)}`);
  }
  for (let i = 0; i < targets.length; i++) {
    for (let j = i + 1; j < targets.length; j++) {
      const a = targets[i];
      const b = targets[j];
      if (a === b || a.startsWith(`${b}/`) || b.startsWith(`${a}/`)) {
        throw fail('ERR_INVALID_MANIFEST', `Conflicting targets: ${a} and ${b}`);
      }
    }
  }
}

function approvalSet(grants) {
  if (!Array.isArray(grants)) throw fail('ERR_INVALID_GRANT', 'Grants must be an array');
  const approved = new Set();
  for (let i = 0; i < grants.length; i++) {
    const grant = grants[i];
    if (!isPlainObject(grant) || !hasExactKeys(grant, ['path', 'operation'])
        || !OPERATIONS.has(grant.operation) || !isPortablePath(grant.path)) {
      throw fail('ERR_INVALID_GRANT', 'Each grant must be exactly {path, operation} with a valid path and operation');
    }
    approved.add(`${grant.operation}\0${grant.path}`);
  }
  return approved;
}

async function lstatOrNull(target) {
  try {
    return await fs.lstat(target);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

async function checkTarget(root, relative) {
  const segments = relative.split('/');
  let current = root;
  for (let i = 0; i < segments.length; i++) {
    current = path.join(current, segments[i]);
    const stats = await lstatOrNull(current);
    if (stats === null) return;
    if (stats.isSymbolicLink()) throw fail('ERR_UNSAFE_TARGET', `Symbolic link in target path: ${relative}`);
    const isLast = i === segments.length - 1;
    if (isLast ? !stats.isFile() : !stats.isDirectory()) {
      throw fail('ERR_UNSAFE_TARGET', `Unsafe target: ${relative}`);
    }
  }
}

export async function restore(directory, manifest, grants) {
  validateManifest(manifest);
  const approved = approvalSet(grants);

  for (const item of manifest.writes) {
    if (!approved.has(`write\0${item.path}`)) throw fail('ERR_DENIED', `Write not approved: ${item.path}`);
  }
  for (const relative of manifest.deletes) {
    if (!approved.has(`delete\0${relative}`)) throw fail('ERR_DENIED', `Delete not approved: ${relative}`);
  }

  const root = path.resolve(directory);
  const rootStats = await fs.lstat(root);
  if (rootStats.isSymbolicLink() || !rootStats.isDirectory()) {
    throw fail('ERR_UNSAFE_TARGET', 'Root must be a real directory');
  }
  for (const item of manifest.writes) await checkTarget(root, item.path);
  for (const relative of manifest.deletes) await checkTarget(root, relative);

  const written = [];
  const deleted = [];
  for (const item of manifest.writes) {
    const target = path.join(root, ...item.path.split('/'));
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, item.content, 'utf8');
    written.push(item.path);
  }
  for (const relative of manifest.deletes) {
    try {
      await fs.unlink(path.join(root, ...relative.split('/')));
      deleted.push(relative);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
  }
  return { written, deleted };
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { restore } from './src/restore.js';

const results = [];
async function expect(name, fn, code) {
  try { const r = await fn(); results.push(`${code ? 'FAIL' : 'ok  '} ${name} -> ${JSON.stringify(r)}`); }
  catch (e) { results.push(`${e.code === code ? 'ok  ' : 'FAIL'} ${name} -> ${e.code}`); }
}
const d = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-smoke-'));
const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-out-'));
await fs.writeFile(path.join(outside, 'secret.txt'), 'outside');
await fs.writeFile(path.join(d, '.hidden'), 'h');
await fs.mkdir(path.join(d, 'sub'));
await fs.writeFile(path.join(d, 'sub', 'old.txt'), 'old');
await fs.symlink(outside, path.join(d, 'link'), 'junction');
await fs.symlink(path.join(d, 'sub'), path.join(d, 'inlink'), 'junction');
const W = (p, c = 'x') => ({ path: p, content: c });
const g = (p, operation = 'write') => ({ path: p, operation });

await expect('approved flag', () => restore(d, { writes: [W('a.txt')], deletes: [], approved: true }, []), 'ERR_INVALID_MANIFEST');
await expect('extra write field', () => restore(d, { writes: [{ path: 'a.txt', content: 'x', replace: true }], deletes: [] }, [g('a.txt')]), 'ERR_INVALID_MANIFEST');
await expect('non-string content', () => restore(d, { writes: [{ path: 'a.txt', content: 1 }], deletes: [] }, [g('a.txt')]), 'ERR_INVALID_MANIFEST');
await expect('missing deletes', () => restore(d, { writes: [] }, []), 'ERR_INVALID_MANIFEST');
await expect('dup write/delete', () => restore(d, { writes: [W('a.txt')], deletes: ['a.txt'] }, [g('a.txt'), g('a.txt', 'delete')]), 'ERR_INVALID_MANIFEST');
await expect('ancestor', () => restore(d, { writes: [W('a'), W('a/b')], deletes: [] }, [g('a'), g('a/b')]), 'ERR_INVALID_MANIFEST');
for (const p of ['../x', '/abs', 'a//b', 'A.txt', 'a\\b', 'c:x', 'con', 'nul.txt', 'com1.tar.gz', './a', 'a/', '']) {
  await expect(`path ${JSON.stringify(p)}`, () => restore(d, { writes: [W(p)], deletes: [] }, []), 'ERR_INVALID_PATH');
}
await expect('bad grant op', () => restore(d, { writes: [], deletes: [] }, [g('a.txt', 'read')]), 'ERR_INVALID_GRANT');
await expect('bad grant path', () => restore(d, { writes: [], deletes: [] }, [g('../a')]), 'ERR_INVALID_GRANT');
await expect('grants not array', () => restore(d, { writes: [], deletes: [] }, {}), 'ERR_INVALID_GRANT');
await expect('prefix grant', () => restore(d, { writes: [W('sub/new.txt')], deletes: [] }, [g('sub')]), 'ERR_DENIED');
await expect('wrong op grant', () => restore(d, { writes: [], deletes: ['sub/old.txt'] }, [g('sub/old.txt')]), 'ERR_DENIED');
await expect('partial deny no mkdir', () => restore(d, { writes: [W('fresh/a.txt'), W('b.txt')], deletes: [] }, [g('fresh/a.txt')]), 'ERR_DENIED');
await expect('junction outside', () => restore(d, { writes: [W('link/secret.txt', 'pwned')], deletes: [] }, [g('link/secret.txt')]), 'ERR_UNSAFE_TARGET');
await expect('junction inside', () => restore(d, { writes: [], deletes: ['inlink/old.txt'] }, [g('inlink/old.txt', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('directory target', () => restore(d, { writes: [], deletes: ['sub'] }, [g('sub', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('file as ancestor', () => restore(d, { writes: [W('sub/old.txt/x')], deletes: [] }, [g('sub/old.txt/x')]), 'ERR_UNSAFE_TARGET');
await expect('unsafe after valid no mkdir', () => restore(d, { writes: [W('fresh2/a.txt'), W('link/z')], deletes: [] }, [g('fresh2/a.txt'), g('link/z')]), 'ERR_UNSAFE_TARGET');
await expect('success', () => restore(d, { writes: [W('sub/old.txt', 'new'), W('n/m/k.txt')], deletes: ['gone.txt', '.hidden2'.replace('.', 'h')] },
  [g('sub/old.txt'), g('sub/old.txt'), g('n/m/k.txt'), g('gone.txt', 'delete'), g('hhidden2', 'delete')]));
await fs.writeFile(path.join(d, 'del.txt'), 'd');
await expect('delete', () => restore(d, { writes: [], deletes: ['del.txt'] }, [g('del.txt', 'delete')]));

results.push('outside: ' + await fs.readFile(path.join(outside, 'secret.txt'), 'utf8'));
results.push('root entries: ' + (await fs.readdir(d)).sort().join(','));
results.push('sub/old.txt: ' + await fs.readFile(path.join(d, 'sub', 'old.txt'), 'utf8'));
console.log(results.join('\n'));
await fs.rm(path.join(d, 'link')); await fs.rm(path.join(d, 'inlink'));
await fs.rm(d, { recursive: true }); await fs.rm(outside, { recursive: true });
